uniform vec3 uZenith;
uniform vec3 uMid;
uniform vec3 uHorizon;
uniform vec3 uLightCol;
uniform vec3 uSunDir;
uniform vec3 uMoonDir;
uniform vec4 uBodies;
uniform vec4 uSkyHalo;
uniform float uSunrise;
uniform float uPoster;
uniform vec2 uTilt;

vec3 toSky(vec3 d) { return vec3(d.x, d.y * uTilt.x - d.z * uTilt.y, d.z * uTilt.x + d.y * uTilt.y); }
vec3 skyGradient(vec3 d) {
  float h = d.y;
  float a = smoothstep(-0.03, 0.16, h);
  float b = smoothstep(0.1, 0.42, h);
  if (uPoster > 0.5) {
    float n = uPoster;
    a = floor(a * n + 0.5) / n;
    b = floor(b * n + 0.5) / n;
  }
  vec3 c = mix(uHorizon, uMid, a);
  c = mix(c, uZenith, b);

  vec2 dz = normalize(d.xz + vec2(1e-5));
  vec2 sz = normalize(uSunDir.xz + vec2(1e-5));
  float az = max(dot(dz, sz), 0.0);
  float band = exp(-abs(h - max(uSunDir.y, -0.02) * 0.6) * 9.0) * pow(az, uSkyHalo.x);
  c += uLightCol * band * uBodies.y * uSkyHalo.y;

  float cm = max(dot(d, uMoonDir), 0.0);
  c += uLightCol * pow(cm, 6.0) * uBodies.z * 0.12;
  return c;
}

uniform float uTime;
uniform sampler2D uNoise;
uniform vec3 uFogCol;
uniform vec3 uRimCol;
uniform vec3 uLightDir;
uniform float uLightAmt;
uniform vec3 uLayerCol[5];
uniform float uLayerZ[5];
uniform vec4 uFog;
uniform float uMistH;
uniform float uFarK;
uniform float uMistDist;
uniform float uRoadClean;
uniform float uFarHz;
uniform vec3 uGroundCtl;
uniform float uFogLow;
uniform vec4 uRimCtl;
uniform vec3 uSunAnchor;

uniform int uGlowN;
uniform vec4 uDarkX;
uniform float uDarkK;
uniform float uDarkMul;
uniform vec4 uGlowPos[8];
uniform vec3 uGlowCol[8];
uniform float uGlowSoft;
float ffDark(vec3 W) {
  float kx = smoothstep(uDarkX.x - uDarkX.z, uDarkX.x, W.x) * (1.0 - smoothstep(uDarkX.y, uDarkX.y + uDarkX.w, W.x));

  float kz = smoothstep(-26.0, -9.0, W.z);
  return kx * kz * uDarkK;
}
vec3 ffLight(vec3 W, vec3 N, float wrapK) {
  vec3 s = vec3(0.0);
  for (int i = 0; i < uGlowN; i++) {
    vec3 Lp = uGlowPos[i].xyz - W;
    float d = length(Lp);
    float R = max(uGlowPos[i].w, 1e-3);
    float g = clamp((R - d) / (R * 0.55), 0.0, 1.0);
    g = g * g * (3.0 - 2.0 * g);
    float gt = max(1.0 - d / R, 0.0);
    g = mix(g, gt * gt * gt, uGlowSoft);
    s += uGlowCol[i] * g * (wrapK + (1.0 - wrapK) * max(dot(N, Lp / max(d, 1e-3)), 0.0));
  }
  return s;
}

float gGround = 0.0;
vec3 skyOnGround(vec3 W, float flr) {
  if (uGroundCtl.x <= 0.0) return vec3(0.0);
  float zk = smoothstep(-8.0, -3.0, W.z) * mix(1.0, 0.25, smoothstep(-1.5, 9.0, W.z));

  float a = texture2D(uNoise, W.xz * vec2(0.083, 0.47) + vec2(0.13, 0.71)).r;
  float a2 = texture2D(uNoise, W.xz * vec2(0.21, 1.13) + vec2(0.59, 0.29)).b;
  float b = texture2D(uNoise, W.xz * vec2(0.61, 2.9) + 0.37).g;
  float pk = 0.3 + 1.4 * mix(a * 0.4 + a2 * 0.35 + b * 0.25, a * 0.6 + a2 * 0.4, gGround);
  float ns = (W.x - uSunAnchor.x) / 10.0;
  float warmK = exp(-ns * ns) * (1.0 - smoothstep(-1.0, 8.0, W.z));

  vec3 skyC = mix(mix(vec3(0.34, 0.40, 0.50), vec3(0.42, 0.42, 0.44), uSunrise), mix(vec3(0.52, 0.41, 0.29), vec3(0.42, 0.43, 0.47), gGround), warmK);
  return skyC * 0.05 * uGroundCtl.x * flr * zk * pk;
}
vec3 layerColor(float z) {
  if (z >= uLayerZ[0]) return uLayerCol[0];
  for (int i = 0; i < 4; i++) {
    if (z >= uLayerZ[i + 1]) {
      float k = (z - uLayerZ[i + 1]) / (uLayerZ[i] - uLayerZ[i + 1]);
      return mix(uLayerCol[i + 1], uLayerCol[i], k);
    }
  }
  return mix(uLayerCol[4], uHorizon, clamp((uLayerZ[4] - z) / 260.0, 0.0, uFarHz));
}
vec3 mistOver(vec3 col, vec3 W, float amt) {
  vec3 Vd = normalize(W - cameraPosition);
  float d = length(cameraPosition - W);
  float hgt = max(W.y - uFog.z, 0.0);
  float wisp = texture2D(uNoise, W.xz * vec2(0.018, 0.05) + vec2(uTime * 0.012, 0.0)).r;
  float wisp2 = texture2D(uNoise, W.xy * vec2(0.03, 0.08) + vec2(-uTime * 0.008, uTime * 0.003)).g;
  float layerH = (0.6 + uFog.y * 7.0) * uMistH;
  float mist = uFog.x * uFog.w * exp(-hgt / layerH) * smoothstep(8.0, 70.0, d) * (0.55 + 0.9 * wisp * wisp2);
  mist += uFog.x * 0.22 * smoothstep(40.0, 300.0, d) * uMistDist;
  float dense = smoothstep(0.5, 0.78, uFog.x);
  mist += dense * (0.62 * smoothstep(12.0, 75.0, d) + 0.35 * exp(-hgt / (layerH * 1.6)) * smoothstep(6.0, 30.0, d)) * (0.7 + 0.6 * wisp);

  mist *= 1.0 - uRoadClean * smoothstep(-9.0, -3.0, W.z);
  mist = clamp(mist * amt, 0.0, 0.95);
  vec3 sv = toSky(Vd);
  float sc = pow(max(dot(sv, uLightDir), 0.0), 12.0);
  vec3 fogC = mix(uFogCol, skyGradient(sv), 0.35 * mix(1.0, smoothstep(0.0, 0.1, sv.y), uFogLow)) + uLightCol * sc * 0.25 * uLightAmt;
  return mix(col, fogC, mist);
}
uniform float uFadeAll;
uniform float uSkyK;
uniform vec3 uBark;
uniform float uRim;
uniform float uValue;
uniform float uMist;
uniform float uJitter;
uniform float uLayerShift;
uniform float uTrueZ;
uniform float uGrain;
uniform float uForm;
uniform float uSoilK;
uniform vec3 uTint;
uniform float uTintK;
uniform vec2 uCave;
uniform vec3 uCaveX;


float rtLum(vec3 c) { return dot(c, vec3(0.3, 0.55, 0.15)); }

float rtBase(float z) { float sk = rtLum(uMid); return (1.5 * rtLum(layerColor(min(z + 2.0, 0.0))) + 0.0415 * sk + 0.055 * (1.0 - smoothstep(0.0, 0.15, sk))) * 1.00; }

vec3 rtTint() { vec3 s = mix(uMid, uHorizon, 0.08); return mix(s / max(rtLum(s), 1e-4), vec3(0.92, 0.97, 1.2), uGlowSoft); }

float rtFall(float z) { return mix(1.0, mix(0.74, 0.62, uGlowSoft), smoothstep(-1.7, 2.2, z)) * mix(1.0, 0.50, smoothstep(2.2, 9.0, z)); }
vec3 rtKeyDir(vec3 W) { return normalize(vec3(uSunAnchor.x, uSunAnchor.y + 3.5, max(4.5, W.z + 3.5)) - W); }

vec3 roadTone(vec3 N, vec3 W) { return rtTint() * rtBase(W.z) * mix(0.74, 1.12, smoothstep(0.1, 0.6, dot(N, rtKeyDir(W)))) * rtFall(W.z); }

vec3 roadRim(vec3 W) {
  float w = texture2D(uNoise, W.xz * vec2(0.09, 0.05)).g - 0.5;
  float r = smoothstep(-2.3, -1.5, W.z + w * 0.5) * (1.0 - smoothstep(-1.2, -0.3, W.z + w * 0.9));

  return rtTint() * rtBase(W.z) * mix(0.15, 1.0, uGlowSoft) * 0.35 * r * smoothstep(0.35, 0.6, texture2D(uNoise, vec2(W.x * 0.04, 0.3)).r);
}

vec3 roadLamp(vec3 ffl, vec3 W, vec3 N, float k) {
  vec3 Lp = uGlowPos[0].xyz - W;
  float d = length(Lp), R = max(uGlowPos[0].w, 1e-3);
  float gt = max(1.0 - d / R, 0.0);
  vec3 h0 = uGlowCol[0] * mix(smoothstep(0.0, 1.0, clamp((R - d) / (R * 0.55), 0.0, 1.0)), gt * gt * gt, uGlowSoft) * (0.3 + 0.7 * max(dot(N, Lp / max(d, 1e-3)), 0.0));
  float t = max(1.0 - length(Lp.xz) / 3.00, 0.0);
  return ffl + h0 * k * uGlowSoft * (0.34 * t * t - 1.0);
}

varying vec3 vWorld;
varying vec3 vNormalW;
varying vec3 vOrigin;

void main() {
  vec3 V = normalize(cameraPosition - vWorld);
  float nl = length(vNormalW);
  vec3 N = nl > 1e-4 ? vNormalW / nl : V;
  #ifdef DOUBLE_SIDED
    N = gl_FrontFacing ? N : -N;
  #endif
  float rimBoost = 1.0;
  #ifdef CLIP_CAVE
    float lx = vWorld.x - uCave.x;
    float ly = vWorld.y - uCave.y;
    float ay = arch(lx);
    if (ly < ay && lx > uCaveX.x) discard;
    rimBoost += (1.0 - smoothstep(ay, ay + 0.4, ly)) * smoothstep(uCaveX.y, uCaveX.z, lx) * 1.4;
  #endif
  float lz = mix(vWorld.z, vOrigin.z, 0.75 * (1.0 - uTrueZ)) + uLayerShift;

  vec3 col = layerColor(lz) * uValue;
  gGround = 1.0;
  float ph = fract(sin(dot(floor(vOrigin.xz * 2.0), vec2(12.9898, 78.233))) * 43758.5453);
  col *= 1.0 + uJitter * (ph * 2.0 - 1.0);
  col = mix(col, uTint, uTintK);
  if (uGrain > 0.0) {


    vec2 gp = N.y > 0.7 ? vWorld.xz * vec2(1.0, 2.2) : vWorld.xy;
    float g = texture2D(uNoise, gp * vec2(0.34, 0.09) + vWorld.z * 0.11).g * 0.6 + texture2D(uNoise, gp * vec2(1.1, 0.27)).b * 0.4;
    col *= 1.0 + (g - 0.5) * uGrain * 1.6;
  }
  col += uZenith * 0.05 * max(N.y, 0.0) * uRimCtl.w;

  vec2 toSun = normalize(uSunAnchor.xy - vWorld.xy + vec2(1e-3));
  col += skyOnGround(vWorld, mix(smoothstep(0.25, 0.95, N.y), 1.0, gGround * step(-1.7, vWorld.z))) * uSkyK * clamp(1.0 + 1.2 * N.x * toSun.x, 0.6, 1.35);
  vec2 L2 = normalize(mix(uLightDir.xy, uSunAnchor.xy - vWorld.xy, uRimCtl.z) + vec2(1e-4));
  vec2 N2 = normalize(N.xy + vec2(1e-4));
  float fres = 1.0 - abs(dot(N, V));
  float rimShape = smoothstep(0.84, 0.99, fres);
  rimShape *= 1.0 - 0.85 * smoothstep(0.75, 0.97, N.y);
  float facing = smoothstep(-0.1, 0.75, dot(N2, L2));
  float depthK = clamp(1.0 - (-vOrigin.z - 6.0) / 120.0, 0.25, 1.0);
  col += uRimCol * rimShape * facing * (uRim < 0.15 ? abs(uRim) : max(uRim, uRimCtl.x * smoothstep(-40.0, -20.0, vWorld.z))) * rimBoost * uLightAmt * depthK * 0.7;

  if (uForm > 0.0) col += uRimCol * uForm * uLightAmt * smoothstep(0.1, 0.95, dot(N2, L2)) * (1.0 - abs(N.z)) ;
  float barkN = 0.0;
  if (uBark.x + uBark.y > 0.0) {
    float b1 = texture2D(uNoise, vWorld.xy * vec2(1.3, 0.17) + vWorld.z * 0.07).g;
    float b2 = texture2D(uNoise, vWorld.xy * vec2(3.7, 0.45) + 0.31).r;
    barkN = mix(smoothstep(0.3, 0.72, b1 * 0.6 + b2 * 0.4), 0.55, smoothstep(1.2, 2.2, abs(vWorld.x - uBark.z)));
    vec2 toA = normalize(uSunAnchor.xy - vWorld.xy + vec2(1e-3));

    float side = smoothstep(-0.55, 0.6, dot(N.xy, toA));

    col += mix(mix(uZenith, uMid, 0.5) * 0.35, uLightCol, side) * uBark.x * (0.25 + 0.75 * side) * (0.35 + 0.9 * barkN);
  }
  float mistAmt = uMist;
  {
  float gdT = smoothstep(4.60 - 0.05, 4.60 + 0.7, vWorld.z);
  float gdN = dot(N, rtKeyDir(vWorld));
  float gdY = rtBase(0.0) * mix(1.30, 1.0, uGlowSoft);
  vec3 gdC = rtTint();
  vec3 gdO = gdC * gdY * 0.42 * mix(1.15, 0.7, gdT);

  float gdB = smoothstep(0.32, 0.62, texture2D(uNoise, vec2(vWorld.x * 0.045 + 0.00, 0.21)).r);
  gdO += gdC * gdY * mix(0.6, 1.0, uGlowSoft) * 0.24 * (1.0 - smoothstep(0.0, 0.1, gdT)) * smoothstep(0.1, 0.55, gdN) * gdB;

  float gdE = (1.0 - smoothstep(-24.00, -8.00, vWorld.x)) + smoothstep(68.00, 84.00, vWorld.x);
  col = mix(gdO * 0.750, roadTone(vec3(0.0, 1.0, 0.0), vWorld), clamp(gdE, 0.0, 1.0));

}

  float ffd = ffDark(vWorld);
  col = mistOver(col, vWorld, mistAmt * (1.0 - ffd * 0.9));
  col *= mix(1.0, uDarkMul, ffd);
  vec3 ffl = ffLight(vWorld, N, 0.3);


  float flr = smoothstep(0.55, 0.95, N.y);
  float soil = mix(1.0, 0.25 + 1.5 * texture2D(uNoise, vWorld.xz * vec2(1.9, 0.7)).r * texture2D(uNoise, vWorld.xz * vec2(5.3, 1.7)).g * 2.0, uGlowSoft * flr * uSoilK);

  col += ffl * (0.5 * (1.0 - 0.8 * N.z * N.z) + mix(1.6, 0.12, uRimCtl.z) * rimShape + 0.45 * flr) * soil * mix(1.0, max(uSkyK, 0.25), uGlowSoft);

  col += ffl * uBark.y * (0.3 + 0.9 * barkN) * vec3(1.0, 0.82, 0.62);
  #ifdef CAVE_FLOOR

    float caveK = smoothstep(uCaveX.x, uCaveX.y, vWorld.x - uCave.x) * (1.0 - smoothstep(0.6, 2.2, vWorld.z));
    col = mix(col, vec3(0.0125, 0.0065, 0.0095), caveK);
  #endif



  float farFade = (1.0 - uFarK) * max(uFadeAll, 1.0 - smoothstep(-32.0, -16.0, mix(vWorld.z, vOrigin.z, 0.75)));

  if (farFade > 0.985) discard;
  gl_FragColor = vec4(col, 1.0 - farFade);
}

