uniform vec2 uCave;
uniform vec3 uCaveX;


float rtLum(vec3 c) { return dot(c, vec3(0.3, 0.55, 0.15)); }

float rtBase(float z) { float sk = rtLum(uMid); return (1.5 * rtLum(layerColor(min(z + 2.0, 0.0))) + 0.0415 * sk + 0.055 * (1.0 - smoothstep(0.0, 0.15, sk))) * 1.00; }

vec3 rtTint() { vec3 s = mix(uMid, uHorizon, 0.08); return mix(s / max(rtLum(s), 1e-4), vec3(0.92, 0.97, 1.2), uGlowSoft); }

float rtFall(float z) { return mix(1.0, mix(0.74, 0.62, uGlowSoft), smoothstep(-1.7, 2.2, z)) * mix(1.0, 0.50, smoothstep(2.2, 9.0, z)); }
vec3 rtKeyDir(vec3 W) { return normalize(vec3(uSunAnchor.x, uSunAnchor.y + 3.5, max(4.5, W.z + 3.5)) - W); }

vec3 roadTone(vec3 N, vec3 W) { return rtTint() * rtBase(W.z) * mix(0.74, 1.12, smoothstep(0.1, 0.6, dot(N, rtKeyDir(W)))) * rtFall(W.z); }

vec3 roadRim(vec3 W) {
  float w = texture2D(uNoise, W.xz * vec2(0.09, 0.05)).g - 0.5;
  float r = smoothstep(-2.3, -1.5, W.z + w * 0.5) * (1.0 - smoothstep(-1.2, -0.3, W.z + w * 0.9));

  return rtTint() * rtBase(W.z) * mix(0.15, 1.0, uGlowSoft) * 0.35 * r * smoothstep(0.35, 0.6, texture2D(uNoise, vec2(W.x * 0.04, 0.3)).r);
}

vec3 roadLamp(vec3 ffl, vec3 W, vec3 N, float k) {
  vec3 Lp = uGlowPos[0].xyz - W;
  float d = length(Lp), R = max(uGlowPos[0].w, 1e-3);
  float gt = max(1.0 - d / R, 0.0);
  vec3 h0 = uGlowCol[0] * mix(smoothstep(0.0, 1.0, clamp((R - d) / (R * 0.55), 0.0, 1.0)), gt * gt * gt, uGlowSoft) * (0.3 + 0.7 * max(dot(N, Lp / max(d, 1e-3)), 0.0));
  float t = max(1.0 - length(Lp.xz) / 3.00, 0.0);
  return ffl + h0 * k * uGlowSoft * (0.34 * t * t - 1.0);
}

varying vec3 vWorld;
varying vec3 vNormalW;
varying vec3 vOrigin;

void main() {
  vec3 V = normalize(cameraPosition - vWorld);
  float nl = length(vNormalW);
  vec3 N = nl > 1e-4 ? vNormalW / nl : V;
  #ifdef DOUBLE_SIDED
    N = gl_FrontFacing ? N : -N;
  #endif
  float rimBoost = 1.0;
  #ifdef CLIP_CAVE
    float lx = vWorld.x - uCave.x;
    float ly = vWorld.y - uCave.y;
    float ay = arch(lx);
    if (ly < ay && lx > uCaveX.x) discard;
    rimBoost += (1.0 - smoothstep(ay, ay + 0.4, ly)) * smoothstep(uCaveX.y, uCaveX.z, lx) * 1.4;
  #endif
  float lz = mix(vWorld.z, vOrigin.z, 0.75 * (1.0 - uTrueZ)) + uLayerShift;

  vec3 col = layerColor(lz) * uValue;
  gGround = 1.0;
  float ph = fract(sin(dot(floor(vOrigin.xz * 2.0), vec2(12.9898, 78.233))) * 43758.5453);
  col *= 1.0 + uJitter * (ph * 2.0 - 1.0);
  col = mix(col, uTint, uTintK);
  if (uGrain > 0.0) {


    vec2 gp = N.y > 0.7 ? vWorld.xz * vec2(1.0, 2.2) : vWorld.xy;
    float g = texture2D(uNoise, gp * vec2(0.34, 0.09) + vWorld.z * 0.11).g * 0.6 + texture2D(uNoise, gp * vec2(1.1, 0.27)).b * 0.4;
    col *= 1.0 + (g - 0.5) * uGrain * 1.6;
  }
  col += uZenith * 0.05 * max(N.y, 0.0) * uRimCtl.w;

  vec2 toSun = normalize(uSunAnchor.xy - vWorld.xy + vec2(1e-3));
  col += skyOnGround(vWorld, mix(smoothstep(0.25, 0.95, N.y), 1.0, gGround * step(-1.7, vWorld.z))) * uSkyK * clamp(1.0 + 1.2 * N.x * toSun.x, 0.6, 1.35);
  vec2 L2 = normalize(mix(uLightDir.xy, uSunAnchor.xy - vWorld.xy, uRimCtl.z) + vec2(1e-4));
  vec2 N2 = normalize(N.xy + vec2(1e-4));
  float fres = 1.0 - abs(dot(N, V));
  float rimShape = smoothstep(0.84, 0.99, fres);
  rimShape *= 1.0 - 0.85 * smoothstep(0.75, 0.97, N.y);
  float facing = smoothstep(-0.1, 0.75, dot(N2, L2));
  float depthK = clamp(1.0 - (-vOrigin.z - 6.0) / 120.0, 0.25, 1.0);
  col += uRimCol * rimShape * facing * (uRim < 0.15 ? abs(uRim) : max(uRim, uRimCtl.x * smoothstep(-40.0, -20.0, vWorld.z))) * rimBoost * uLightAmt * depthK * 0.7;

  if (uForm > 0.0) col += uRimCol * uForm * uLightAmt * smoothstep(0.1, 0.95, dot(N2, L2)) * (1.0 - abs(N.z)) ;
  float barkN = 0.0;
  if (uBark.x + uBark.y > 0.0) {
    float b1 = texture2D(uNoise, vWorld.xy * vec2(1.3, 0.17) + vWorld.z * 0.07).g;
    float b2 = texture2D(uNoise, vWorld.xy * vec2(3.7, 0.45) + 0.31).r;
    barkN = mix(smoothstep(0.3, 0.72, b1 * 0.6 + b2 * 0.4), 0.55, smoothstep(1.2, 2.2, abs(vWorld.x - uBark.z)));
    vec2 toA = normalize(uSunAnchor.xy - vWorld.xy + vec2(1e-3));

    float side = smoothstep(-0.55, 0.6, dot(N.xy, toA));

    col += mix(mix(uZenith, uMid, 0.5) * 0.35, uLightCol, side) * uBark.x * (0.25 + 0.75 * side) * (0.35 + 0.9 * barkN);
  }
  float mistAmt = uMist;
  {
  vec3 gsL = normalize(vec3(uSunAnchor.x, uSunAnchor.y + 3.5, max(4.5, vWorld.z + 3.5)) - vWorld);
  float gsN = dot(N, gsL);
  vec3 gsB = layerColor(lz);
  float gsY = max(dot(gsB, vec3(0.3, 0.55, 0.15)), 0.004) + 0.0000;

  vec3 gsC = mix(mix(vec3(0.74, 0.92, 1.42), rtTint(), smoothstep(0.12, 0.25, rtLum(uMid)) * (1.0 - uGlowSoft)), gsB / max(dot(gsB, vec3(0.3, 0.55, 0.15)), 0.001), 0.00);
  vec3 gsO = gsC * gsY * mix(0.66, 1.2, smoothstep(0.05, 0.5, gsN));
  gsO = mix(gsO, gsC * (gsY * 1.2 + 0.0010 + 0.002), smoothstep(0.5, 0.78, gsN));
  gsO = mix(gsO, gsC * (gsY * 1.2 + 0.044), smoothstep(0.76, 0.95, gsN) * 0.10);
  col = gsO * 0.62;




}

  float ffd = ffDark(vWorld);
  col = mistOver(col, vWorld, mistAmt * (1.0 - ffd * 0.9));
  col *= mix(1.0, uDarkMul, ffd);
  vec3 ffl = ffLight(vWorld, N, 0.3);


  float flr = smoothstep(0.55, 0.95, N.y);
  float soil = mix(1.0, 0.25 + 1.5 * texture2D(uNoise, vWorld.xz * vec2(1.9, 0.7)).r * texture2D(uNoise, vWorld.xz * vec2(5.3, 1.7)).g * 2.0, uGlowSoft * flr * uSoilK);

  col += ffl * (0.5 * (1.0 - 0.8 * N.z * N.z) + mix(1.6, 0.12, uRimCtl.z) * rimShape + 0.45 * flr) * soil * mix(1.0, max(uSkyK, 0.25), uGlowSoft);

  col += ffl * uBark.y * (0.3 + 0.9 * barkN) * vec3(1.0, 0.82, 0.62);
  #ifdef CAVE_FLOOR

    float caveK = smoothstep(uCaveX.x, uCaveX.y, vWorld.x - uCave.x) * (1.0 - smoothstep(0.6, 2.2, vWorld.z));
    col = mix(col, vec3(0.0125, 0.0065, 0.0095), caveK);
  #endif



  float farFade = (1.0 - uFarK) * max(uFadeAll, 1.0 - smoothstep(-32.0, -16.0, mix(vWorld.z, vOrigin.z, 0.75)));

  if (farFade > 0.985) discard;
  gl_FragColor = vec4(col, 1.0 - farFade);
}

