    barkN = mix(smoothstep(0.3, 0.72, b1 * 0.6 + b2 * 0.4), 0.55, smoothstep(1.2, 2.2, abs(vWorld.x - uBark.z)));
    vec2 toA = normalize(uSunAnchor.xy - vWorld.xy + vec2(1e-3));

    float side = smoothstep(-0.55, 0.6, dot(N.xy, toA));

    col += mix(mix(uZenith, uMid, 0.5) * 0.35, uLightCol, side) * uBark.x * (0.25 + 0.75 * side) * (0.35 + 0.9 * barkN);
  }
  float mistAmt = uMist;
  {
  float gdT = smoothstep(3.50 - 0.05, 3.50 + 0.7, vWorld.z);
  float gdN = dot(N, rtKeyDir(vWorld));
  float gdY = rtBase(0.0) * mix(1.30, 1.0, uGlowSoft);
  vec3 gdC = rtTint();
  vec3 gdO = gdC * gdY * 0.42 * mix(1.25, 0.72, gdT);

  float gdB = smoothstep(0.32, 0.62, texture2D(uNoise, vec2(vWorld.x * 0.045 + 0.00, 0.21)).r);
  {

    float gdNight = smoothstep(96.0, 101.0, vWorld.x) * (1.0 - smoothstep(218.0, 224.0, vWorld.x));
    vec3 gdB0 = gdO;
    vec3 gdOldO = mix(gdB0, gdC * rtBase(0.0) * 0.0 + gdB0 * 1.0, (1.0 - smoothstep(0.02, 0.2, gdT)) * smoothstep(0.2, 0.42, N.y) * (0.45 + 0.55 * gdB));



    vec3 gdNewO = mix(rtTint() * rtBase(0.0) * 0.3, roadTone(vec3(0.0, 1.0, 0.0), vWorld) * (1.0 - 0.55 * smoothstep(1.3, 3.2, vWorld.z + (texture2D(uNoise, vec2(vWorld.x * 0.07, 0.43)).r - 0.5) * 2.4 * smoothstep(1.3, 2.3, vWorld.z))), 1.0 - smoothstep(0.0, 0.25, gdT));


    { float npA = texture2D(uNoise, vec2(vWorld.x * 0.032 + vWorld.z * 0.02, vWorld.z * 0.05 + 0.41)).r;
      float npB = texture2D(uNoise, vec2(vWorld.x * 0.083 - vWorld.z * 0.03, vWorld.z * 0.1 + 0.73)).g;
      if (vWorld.z < 3.6) gdNewO *= mix(1.0, mix(0.8, 1.14, smoothstep(0.34, 0.66, npA * 0.72 + npB * 0.34)), smoothstep(98.8, 103.0, vWorld.x) * (1.0 - smoothstep(217.0, 222.0, vWorld.x))); }
    gdNewO = mix(gdNewO, rtTint() * rtBase(0.0) * 0.2, smoothstep(198.0, 206.0, vWorld.x + (texture2D(uNoise, vec2(vWorld.y * 0.31, vWorld.z * 0.17 + 0.7)).g - 0.5) * 7.0));
    gdO = mix(gdOldO, gdNewO, gdNight);
  }

  float gdE = (1.0 - smoothstep(78.70, 94.70, vWorld.x)) + smoothstep(100000.00, 100001.00, vWorld.x);
  col = mix(gdO * 1.000, roadTone(vec3(0.0, 1.0, 0.0), vWorld), clamp(gdE, 0.0, 1.0));

