  c = mix(c, vec3(0.0242, 0.0284, 0.0452), smoothstep(0.840, 0.980, nl) * 0.200);
  c += vec3(0.0105, 0.0115, 0.0165) * 0.000 * smoothstep(0.35, 0.95, dot(N, normalize(vec3(-0.45, 0.62, 0.64))));
