  }
  float mistAmt = uMist;
  {
  vec3 gsL = normalize(vec3(uSunAnchor.x, uSunAnchor.y + 3.5, max(4.5, vWorld.z + 3.5)) - vWorld);
  float gsN = dot(N, gsL);
  vec3 gsB = layerColor(lz);
  float gsY = max(dot(gsB, vec3(0.3, 0.55, 0.15)), 0.004) + 0.0280;

  vec3 gsC = mix(mix(vec3(0.92, 0.97, 1.2), rtTint(), smoothstep(0.12, 0.25, rtLum(uMid)) * (1.0 - uGlowSoft)), gsB / max(dot(gsB, vec3(0.3, 0.55, 0.15)), 0.001), 0.00);
  vec3 gsO = gsC * gsY * mix(0.66, 1.2, smoothstep(0.05, 0.5, gsN));
  gsO = mix(gsO, gsC * (gsY * 1.2 + 0.0000 + 0.002), smoothstep(0.5, 0.78, gsN));
  gsO = mix(gsO, gsC * (gsY * 1.2 + 0.044), smoothstep(0.76, 0.95, gsN) * 0.00);
  col = gsO * 0.75;


  col = gsC * gsY * 0.75;


}

  float ffd = ffDark(vWorld);
  col = mistOver(col, vWorld, mistAmt * (1.0 - ffd * 0.9));
  col *= mix(1.0, uDarkMul, ffd);
  vec3 ffl = ffLight(vWorld, N, 0.3);


  float flr = smoothstep(0.55, 0.95, N.y);
  float soil = mix(1.0, 0.25 + 1.5 * texture2D(uNoise, vWorld.xz * vec2(1.9, 0.7)).r * texture2D(uNoise, vWorld.xz * vec2(5.3, 1.7)).g * 2.0, uGlowSoft * flr * uSoilK);

  col += ffl * (0.5 * (1.0 - 0.8 * N.z * N.z) + mix(1.6, 0.12, uRimCtl.z) * rimShape + 0.45 * flr) * soil * mix(1.0, max(uSkyK, 0.25), uGlowSoft);

  col += ffl * uBark.y * (0.3 + 0.9 * barkN) * vec3(1.0, 0.82, 0.62);
