  float patch2 = texture2D(uNoise, vW.xz * vec2(0.13, 0.31)).g - 0.5;

  float wave = sin(vW.x * 0.41) * 1.5 + sin(vW.x * 0.97 + 1.7) * 0.8;
  float band = 1.0 - smoothstep(-2.2, 4.6, vW.z + patch_ * 4.2 + patch2 * 1.8 + wave);
