  vec2 Q = P + warp;
  float calm = smoothstep(0.34, 0.68, texture2D(uNoise, P * vec2(0.043, 0.13) + vec2(uTime * 0.006, 0.31)).b);

  vec2 w1 = texture2D(uNoise, vec2(Q.x * 0.07 + Q.y * 0.05 + uTime * 0.015, Q.y * 0.2 + uTime * 0.03)).rg - 0.5;
