    float rip2 = texture2D(uNoise, vW.xz * vec2(0.22, 9.0) + uTime * vec2(0.035, 0.0)).b;
    c = mix(c, vec3(0.93, 0.94, 0.95), smoothstep(0.7, 0.78, rip2) * (0.15 + 0.3 * fz));

