uniform float uTime;
uniform sampler2D uNoise;
uniform sampler2D uRefl;
uniform sampler2D uShore;
uniform vec4 uBox;
uniform mat4 uReflMat;
uniform vec3 uAxis;
uniform float uSquash;
uniform vec2 uFarEdge;
uniform float uShoreFade;
uniform vec3 uFogCol;
uniform vec3 uSunWorld;
uniform float uLightAmt;
uniform float uGlint;
uniform float uWaterK;
uniform float uShade;
varying vec3 vW;
void main() {
  vec3 P = vW;
  vec3 V = normalize(P - cameraPosition);
  float d = length(P - cameraPosition);

  vec2 warp = (texture2D(uNoise, P.xz * vec2(0.031, 0.067) + uTime * 0.0035).rg - 0.5) * vec2(5.0, 2.2);
  vec2 Q = P.xz + warp;
  float calm = smoothstep(0.34, 0.68, texture2D(uNoise, P.xz * vec2(0.043, 0.13) + vec2(uTime * 0.006, 0.31)).b);
  vec2 w1 = texture2D(uNoise, vec2(Q.x * 0.07 + Q.y * 0.05 + uTime * 0.015, Q.y * 0.2 - uTime * 0.02)).rg - 0.5;
  vec2 w2 = texture2D(uNoise, vec2(Q.x * 0.23 - Q.y * 0.11 - uTime * 0.01, Q.y * 0.62 + uTime * 0.03)).gb - 0.5;
  vec2 wave = (w1 * 0.9 + w2 * 0.35) * mix(0.16, 0.55, calm);
  vec4 tc = uReflMat * vec4(P, 1.0);
  vec2 ruv = tc.xy / tc.w;
  vec4 ft = uReflMat * vec4(uAxis, 1.0);
  float y0 = ft.y / ft.w;
  ruv.y = y0 + (ruv.y - y0) * uSquash;
  ruv += vec2(wave.x * 0.012, wave.y * 0.004);
  vec3 refl = texture2D(uRefl, ruv).rgb * 0.4
    + texture2D(uRefl, ruv + vec2(0.0, 0.004)).rgb * 0.2 + texture2D(uRefl, ruv - vec2(0.0, 0.004)).rgb * 0.2
    + texture2D(uRefl, ruv + vec2(0.0, 0.009)).rgb * 0.1 + texture2D(uRefl, ruv - vec2(0.0, 0.009)).rgb * 0.1;

  vec3 Rn = reflect(V, normalize(vec3(wave.x * 0.05, 1.0, wave.y * 0.05)));
