vec3 surfaceAt(vec3 P) {
  vec3 V = normalize(P - cameraPosition);
  float d = length(P - cameraPosition);

  vec2 warp = (texture2D(uNoise, P.xz * vec2(0.031, 0.067) + uTime * 0.0035).rg - 0.5) * vec2(5.0, 2.2);
  vec2 Q = P.xz + warp;
  float calm = smoothstep(0.34, 0.68, texture2D(uNoise, P.xz * vec2(0.043, 0.13) + vec2(uTime * 0.006, 0.31)).b);
  vec2 w1 = texture2D(uNoise, vec2(Q.x * 0.07 + Q.y * 0.05 + uTime * 0.015, Q.y * 0.2 - uTime * 0.02)).rg - 0.5;
  vec2 w2 = texture2D(uNoise, vec2(Q.x * 0.23 - Q.y * 0.11 - uTime * 0.01, Q.y * 0.62 + uTime * 0.03)).gb - 0.5;

  float rvK = smoothstep(432.0, 440.0, P.x);

  float rvN = rvK * uRiverNew;
  vec2 wave = (w1 * 0.9 + w2 * 0.35) * mix(0.28, 1.0, calm) * mix(1.0, 0.5, rvK) * mix(1.0, 0.45, rvN);
  vec3 N = normalize(vec3(wave.x * 0.18, 1.0, wave.y * 0.12));
  vec4 tc = uReflMat * vec4(P, 1.0);
  vec2 ruv = tc.xy / tc.w + vec2(wave.x * 0.012, wave.y * 0.004);
  float rvS = mix(1.0, 1.8, rvK) * mix(1.0, 0.3, rvN);
  vec3 refl = texture2D(uRefl, ruv).rgb * 0.4
    + texture2D(uRefl, ruv + vec2(0.0, 0.006 * rvS)).rgb * 0.2 + texture2D(uRefl, ruv - vec2(0.0, 0.006 * rvS)).rgb * 0.2
    + texture2D(uRefl, ruv + vec2(0.0, 0.014 * rvS)).rgb * 0.1 + texture2D(uRefl, ruv - vec2(0.0, 0.014 * rvS)).rgb * 0.1;
