  float sc = pow(max(dot(V, uLightDir), 0.0), 3.0);
  float a = (1.0 - smoothstep(0.0, 0.5, length(c))) * vAlpha * (0.1 + 1.1 * sc) * uLightAmt;
  gl_FragColor = vec4(uLightCol * 1.6 * a, 1.0);
}
